import 'package:sqflite/sqflite.dart';
import 'package:pos_app/core/network/cloud_api_client.dart';
import 'package:pos_app/core/storage/secure_token_store.dart';
import 'package:pos_app/core/utils/id_generator.dart';
import 'package:pos_app/database/app_database.dart';

final class EnrollmentRepository {EnrollmentRepository(this._db,this._api,{IdGenerator? ids,SecureTokenStore? tokens}):_ids=ids??const UuidV7Generator(),_tokens=tokens??const SecureTokenStore();final AppDatabase _db;final CloudApiClient _api;final IdGenerator _ids;final SecureTokenStore _tokens;
 Future<String> stableDeviceGlobalId() async {final db=await _db.open();final rows=await db.query('app_settings',columns:['value'],where:'key=?',whereArgs:['pending_enrollment_device_global_id'],limit:1);if(rows.isNotEmpty)return rows.first['value'] as String;final id=_ids.newId();await db.insert('app_settings',{'key':'pending_enrollment_device_global_id','value':id,'updated_at':DateTime.now().toUtc().toIso8601String()},conflictAlgorithm:ConflictAlgorithm.replace);return id;}
 Future<void> redeem({required String code,required String username,required String password,required String deviceName}) async {final deviceGid=await stableDeviceGlobalId();final j=await _api.post('/api/device-enrollment/redeem',{'token':code.trim(),'username':username.trim(),'password':password,'deviceName':deviceName.trim(),'deviceGlobalId':deviceGid},authenticated:false);final auth=Map<String,Object?>.from(j['auth'] as Map);await _tokens.save(accessToken:auth['accessToken'] as String,refreshToken:auth['refreshToken'] as String);final db=await _db.open();await db.transaction((tx) async {final now=DateTime.now().toUtc().toIso8601String();final business=Map<String,Object?>.from(j['business'] as Map);final branch=Map<String,Object?>.from(j['branch'] as Map);final device=Map<String,Object?>.from(j['device'] as Map);final user=Map<String,Object?>.from(j['user'] as Map);final bid=await tx.insert('businesses',{'global_id':business['globalId'],'name':business['name'],'server_version':business['serverVersion']??1,'created_at':now,'updated_at':now},conflictAlgorithm:ConflictAlgorithm.replace);final brid=await tx.insert('branches',{'global_id':branch['globalId'],'business_id':bid,'name':branch['name'],'server_version':branch['serverVersion']??1,'created_at':now,'updated_at':now},conflictAlgorithm:ConflictAlgorithm.replace);await tx.insert('devices',{'global_id':device['globalId'],'branch_id':brid,'name':device['name'],'mode':'AdminReadOnly','server_version':device['serverVersion']??1,'created_at':now,'updated_at':now},conflictAlgorithm:ConflictAlgorithm.replace);await tx.insert('users',{'global_id':user['globalId'],'business_id':bid,'name':user['name'],'username':user['username'],'password_hash':'REMOTE_ONLY','password_salt':'REMOTE_ONLY','role':user['role'],'server_version':user['serverVersion']??1,'created_at':now,'updated_at':now},conflictAlgorithm:ConflictAlgorithm.replace);for(final e in {'local_device_global_id':deviceGid,'active_user_global_id':user['globalId'].toString(),'configured':'1','local_session_authenticated':'1'}.entries){await tx.insert('app_settings',{'key':e.key,'value':e.value,'updated_at':now},conflictAlgorithm:ConflictAlgorithm.replace);}await tx.delete('app_settings',where:'key=?',whereArgs:['pending_enrollment_device_global_id']);});}
}
